import Stripe from 'stripe';

export default async function stripeWebhookHandler(
  { rawBody, stripeSignature, stripeSecretKey, stripeWebhookSecret, defaultTier = 'professional' },
  { logging, http }
) {
  if (!stripeSecretKey || !stripeWebhookSecret) {
    logging.log('Missing Stripe configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }

  if (!rawBody || !stripeSignature) {
    logging.log('Missing rawBody or stripe-signature header');
    http?.status(400);
    return { error: 'Bad request' };
  }

  const stripe = new Stripe(stripeSecretKey, { apiVersion: '2023-10-16' });

  // 1. Verify signature
  let event;
  try {
    event = stripe.webhooks.constructEvent(rawBody, stripeSignature, stripeWebhookSecret);
  } catch (err) {
    logging.log('Webhook signature verification failed:', err.message);
    http?.status(400);
    return { error: 'Invalid signature' };
  }

  logging.log('Verified Stripe event:', event.type, event.id);

  const HANDLED_EVENTS = [
    'checkout.session.completed',
    'customer.subscription.updated',
    'customer.subscription.deleted',
    'invoice.payment_failed'
  ];

  if (!HANDLED_EVENTS.includes(event.type)) {
    logging.log('Unhandled event type, acknowledging:', event.type);
    return { received: true, eventType: event.type };
  }

  // --- Helpers ---

  async function getCustomerId(eventObj) {
    const data = eventObj.data.object;
    // customer field is present on subscription + invoice objects
    if (data.customer) return data.customer;
    // checkout.session may have it too
    if (data.customer) return data.customer;
    return null;
  }

  async function getTierFromSubscription(subscription) {
    // Check product metadata first, fall back to defaultTier
    try {
      const itemData = subscription.items?.data?.[0];
      if (itemData?.price?.product) {
        const product = await stripe.products.retrieve(itemData.price.product);
        if (product.metadata?.ccc_tier) {
          return product.metadata.ccc_tier;
        }
      }
    } catch (err) {
      logging.log('Could not read product metadata, using defaultTier:', err.message);
    }
    return defaultTier;
  }

  async function updateCustomerMetadata(customerId, metadata) {
    logging.log('Updating customer', customerId, 'metadata:', JSON.stringify(metadata));
    await stripe.customers.update(customerId, { metadata });
  }

  // 2. Handle events
  let customerId = null;

  try {
    switch (event.type) {

      case 'checkout.session.completed': {
        const session = event.data.object;
        customerId = session.customer;

        if (!customerId) {
          logging.log('checkout.session.completed: no customer ID on session, skipping');
          break;
        }

        // Only act on subscription-mode checkouts
        if (session.mode !== 'subscription') {
          logging.log('checkout.session.completed: not subscription mode, skipping');
          break;
        }

        const subscriptionId = session.subscription;
        if (!subscriptionId) {
          logging.log('checkout.session.completed: no subscription ID, skipping');
          break;
        }

        const subscription = await stripe.subscriptions.retrieve(subscriptionId, {
          expand: ['items.data.price.product']
        });

        const tier = await getTierFromSubscription(subscription);
        const status = subscription.status === 'active' || subscription.status === 'trialing'
          ? subscription.status
          : subscription.status;

        await updateCustomerMetadata(customerId, {
          ccc_tier: tier,
          ccc_status: status,
          ccc_subscription_id: subscriptionId
        });

        logging.log('checkout.session.completed: set tier=%s status=%s sub=%s', tier, status, subscriptionId);
        break;
      }

      case 'customer.subscription.updated': {
        const subscription = event.data.object;
        customerId = subscription.customer;

        if (!customerId) {
          logging.log('customer.subscription.updated: no customer ID, skipping');
          break;
        }

        // Expand product to read ccc_tier from product metadata if set
        const fullSubscription = await stripe.subscriptions.retrieve(subscription.id, {
          expand: ['items.data.price.product']
        });

        const tier = await getTierFromSubscription(fullSubscription);

        // Map Stripe statuses to our status vocabulary
        let status = fullSubscription.status;
        if (fullSubscription.status === 'past_due') status = 'past_due';
        else if (fullSubscription.status === 'canceled') status = 'canceled';
        else if (fullSubscription.status === 'trialing') status = 'trialing';
        else if (fullSubscription.status === 'active') status = 'active';

        await updateCustomerMetadata(customerId, {
          ccc_tier: tier,
          ccc_status: status,
          ccc_subscription_id: subscription.id
        });

        logging.log('customer.subscription.updated: set tier=%s status=%s', tier, status);
        break;
      }

      case 'customer.subscription.deleted': {
        const subscription = event.data.object;
        customerId = subscription.customer;

        if (!customerId) {
          logging.log('customer.subscription.deleted: no customer ID, skipping');
          break;
        }

        await updateCustomerMetadata(customerId, {
          ccc_tier: 'free',
          ccc_status: 'canceled',
          ccc_subscription_id: ''
        });

        logging.log('customer.subscription.deleted: reset to free/canceled');
        break;
      }

      case 'invoice.payment_failed': {
        const invoice = event.data.object;
        customerId = invoice.customer;

        if (!customerId) {
          logging.log('invoice.payment_failed: no customer ID, skipping');
          break;
        }

        // Only update status — preserve tier and subscription ID
        await updateCustomerMetadata(customerId, {
          ccc_status: 'past_due'
        });

        logging.log('invoice.payment_failed: set status=past_due for customer', customerId);
        break;
      }

    }
  } catch (err) {
    logging.log('Error handling event', event.type, ':', err.message);
    // Return 500 so Stripe retries
    http?.status(500);
    return { error: 'Webhook handler error — Stripe will retry' };
  }

  return { received: true, eventType: event.type, customerId };
}

